'use client';

import Link from 'next/link';
import { useState } from 'react';

export function SiteHeader() {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <header className="topbar">
      <div className="container topbar-inner">
        <Link href="/" className="brand" aria-label="Colexa Biosensor home">
          <img
            src="https://colexabiosensor.com/wp-content/uploads/2023/08/Colexa-Biosensor-LOGO.png"
            alt="Colexa Biosensor"
          />
        </Link>

        <nav className="nav" aria-label="Main navigation">
          <Link href="#products">Products</Link>
          <Link href="#about">About Colexa</Link>
          <Link href="#quality">Research &amp; Quality</Link>
          <Link href="/resources" target="_blank" rel="noreferrer">Resources</Link>
          <Link href="#contact">Contact</Link>
        </nav>

        <div className="header-actions">
          <Link href="#contact" className="primary-btn">Partner With Us</Link>
          <button
            type="button"
            className="nav-toggle"
            aria-label={isOpen ? 'Close navigation menu' : 'Open navigation menu'}
            aria-expanded={isOpen}
            aria-controls="mobile-menu"
            onClick={() => setIsOpen((prev) => !prev)}
          >
            <span />
            <span />
            <span />
          </button>
        </div>
      </div>

      {isOpen && (
        <div id="mobile-menu" className="mobile-menu" role="navigation" aria-label="Mobile navigation">
          <Link href="#products" onClick={() => setIsOpen(false)}>Products</Link>
          <Link href="#about" onClick={() => setIsOpen(false)}>About Colexa</Link>
          <Link href="#quality" onClick={() => setIsOpen(false)}>Research &amp; Quality</Link>
          <Link href="/resources" target="_blank" rel="noreferrer" onClick={() => setIsOpen(false)}>Resources</Link>
          <Link href="#contact" onClick={() => setIsOpen(false)}>Contact</Link>
          <Link href="#contact" className="primary-btn mobile-cta" onClick={() => setIsOpen(false)}>Partner With Us</Link>
        </div>
      )}
    </header>
  );
}
